import React, { useState, useEffect } from 'react';
import './Dashboard.css';

export default function Dashboard({ plans, onExecute }) {
  const [senders, setSenders] = useState([]);
  const [loading, setLoading] = useState(false);
  const [view, setView] = useState('plans'); // plans or senders

  useEffect(() => {
    if (view === 'senders') {
      loadSenders();
    }
  }, [view]);

  const loadSenders = async () => {
    setLoading(true);
    try {
      const res = await fetch('http://localhost:3001/api/senders');
      const data = await res.json();
      setSenders(data);
    } catch (err) {
      console.error('Failed to load senders:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="dashboard">
      <div className="dashboard-tabs">
        <button
          className={view === 'plans' ? 'active' : ''}
          onClick={() => setView('plans')}
        >
          Active Plans ({plans.length})
        </button>
        <button
          className={view === 'senders' ? 'active' : ''}
          onClick={() => setView('senders')}
        >
          All Senders
        </button>
      </div>

      {view === 'plans' && (
        <>
          <h2>Cleanup Plans</h2>
          {plans.length === 0 ? (
            <div className="empty-state">
              <p>No plans yet. Create one to get started!</p>
            </div>
          ) : (
            <div className="plans-grid">
              {plans.map((plan) => (
                <div key={plan.id} className="plan-card">
                  <h3>{plan.name}</h3>
                  <p className="plan-sender">{plan.sender}</p>
                  <div className="plan-actions">
                    <span className="action-badge">{plan.action}</span>
                  </div>
                  {plan.lastExecuted && (
                    <p className="plan-date">Last run: {new Date(plan.lastExecuted).toLocaleDateString()}</p>
                  )}
                  <button
                    className="execute-btn"
                    onClick={() => onExecute(plan.id)}
                  >
                    Execute Plan
                  </button>
                </div>
              ))}
            </div>
          )}
        </>
      )}

      {view === 'senders' && (
        <>
          <h2>Email Senders by Volume</h2>
          {loading ? (
            <div className="loading">Loading senders...</div>
          ) : senders.length === 0 ? (
            <div className="empty-state">
              <p>No senders found. Make sure Gmail is authenticated by creating a plan first.</p>
              <p style={{ fontSize: '0.875rem', color: '#9ca3af', marginTop: '0.5rem' }}>
                The app will scan your Gmail account and show all senders sorted by email count.
              </p>
            </div>
          ) : (
            <div className="senders-table-container">
              <table className="senders-table">
                <thead>
                  <tr>
                    <th>Sender Email</th>
                    <th className="count-col">Count</th>
                    <th className="action-col">Action</th>
                  </tr>
                </thead>
                <tbody>
                  {senders.map((sender) => (
                    <tr key={sender.email}>
                      <td className="sender-email">{sender.email}</td>
                      <td className="count-col">{sender.count.toLocaleString()}</td>
                      <td className="action-col">
                        <button
                          className="small-btn"
                          onClick={() => {
                            // Copy to clipboard for easy plan creation
                            navigator.clipboard.writeText(sender.email);
                            alert(`Copied: ${sender.email}\nGo to "New Plan" to create a cleanup rule.`);
                          }}
                        >
                          Copy
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </>
      )}
    </div>
  );
}
